const url = 'https://careflown8n.app.n8n.cloud/webhook/careflow';
const users = $('Gebruikers ophalen').all().map(i => i.json).filter(u => u && u.session_id && u.email);
const reminders = $input.all().map(i => i.json).filter(r => r && r.session_id);
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Amsterdam' }));
const pad = n => String(n).padStart(2, '0');
const today = now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
const mins = now.getHours() * 60 + now.getMinutes();
function toMin(t, fb) {
  const p = String(t || '').split(':');
  const h = Number(p[0]);
  const m = Number(p[1]);
  if (isNaN(h) || isNaN(m)) { return fb; }
  return h * 60 + m;
}
const TXT = {
  nl: {
    ochtend: { s: 'CareFlow: goedemorgen', b: 'Goedemorgen NAAM,\n\nVergeet u niet uw medicijnen in te nemen?\nWilt u daarna even aangeven hoe u zich voelt?\n\nOpen CareFlow: ' + url },
    middag: { s: 'CareFlow: even bijpraten', b: 'Goedemiddag NAAM,\n\nHoe gaat het vandaag met u? Laat het ons kort weten.\n\nOpen CareFlow: ' + url },
    avond: { s: 'CareFlow: avond-check', b: 'Goedenavond NAAM,\n\nHeeft u vandaag uw medicijnen ingenomen en is verder alles goed?\n\nOpen CareFlow: ' + url }
  },
  en: {
    ochtend: { s: 'CareFlow: good morning', b: 'Good morning NAAM,\n\nPlease remember to take your medication.\nCould you then let us know how you feel?\n\nOpen CareFlow: ' + url },
    middag: { s: 'CareFlow: checking in', b: 'Good afternoon NAAM,\n\nHow are you doing today? Let us know briefly.\n\nOpen CareFlow: ' + url },
    avond: { s: 'CareFlow: evening check', b: 'Good evening NAAM,\n\nDid you take your medication today, and is everything else okay?\n\nOpen CareFlow: ' + url }
  },
  tr: {
    ochtend: { s: 'CareFlow: gunaydin', b: 'Gunaydin NAAM,\n\nIlaclarinizi almayi unutmayin.\nArdindan kendinizi nasil hissettiginizi bildirir misiniz?\n\nCareFlow: ' + url },
    middag: { s: 'CareFlow: nasilsiniz', b: 'Iyi gunler NAAM,\n\nBugun nasilsiniz? Kisaca bize bildirin.\n\nCareFlow: ' + url },
    avond: { s: 'CareFlow: aksam kontrolu', b: 'Iyi aksamlar NAAM,\n\nBugun ilaclarinizi aldiniz mi ve her sey yolunda mi?\n\nCareFlow: ' + url }
  },
  ar: {
    ochtend: { s: 'CareFlow: صباح الخير', b: 'صباح الخير NAAM،\n\nلا تنس تناول أدويتك.\nهل يمكنك بعد ذلك إخبارنا كيف تشعر؟\n\nافتح CareFlow: ' + url },
    middag: { s: 'CareFlow: كيف حالك', b: 'مساء الخير NAAM،\n\nكيف حالك اليوم؟ أخبرنا باختصار.\n\nافتح CareFlow: ' + url },
    avond: { s: 'CareFlow: فحص المساء', b: 'مساء الخير NAAM،\n\nهل تناولت أدويتك اليوم وهل كل شيء على ما يرام؟\n\nافتح CareFlow: ' + url }
  }
};
const out = [];
for (const u of users) {
  if (u.onboarding_complete !== true && u.onboarding_complete !== 'true') { continue; }
  const lang = TXT[u.language] ? u.language : 'nl';
  const perDay = Number(u.reminders_per_day || 2);
  const wake = toMin(u.wake_time, 480);
  const sleep = toMin(u.sleep_time, 1320);
  const slots = [{ type: 'ochtend', at: wake + 30 }];
  if (perDay >= 3) { slots.push({ type: 'middag', at: 13 * 60 }); }
  if (perDay >= 2) { slots.push({ type: 'avond', at: sleep - 60 }); }
  for (const s of slots) {
    if (mins < s.at || mins >= s.at + 30) { continue; }
    const already = reminders.some(r => r.session_id === u.session_id && r.check_type === s.type && String(r.created_at || '').slice(0, 10) === today);
    if (already) { continue; }
    const tx = TXT[lang][s.type];
    out.push({ json: {
      session_id: u.session_id,
      email: u.email,
      name: u.name || '',
      check_type: s.type,
      check_id: s.type + '_' + today + '_' + u.session_id,
      subject: tx.s,
      body: tx.b.split('NAAM').join(u.name || '')
    } });
  }
}
return out;

const url = 'https://careflown8n.app.n8n.cloud/webhook/careflow';
const users = $('Gebruikers (escalatie)').all().map(i => i.json).filter(u => u && u.session_id);
const rows = $input.all().map(i => i.json).filter(r => r && r.session_id && r.status);
const nowMs = Date.now();
const R2 = {
  nl: { s: 'CareFlow: heeft u het gezien?', b: 'Beste NAAM,

We hebben nog geen antwoord van u ontvangen. Wilt u de check-in alsnog invullen?

Open CareFlow: ' + url + '

Als we over 30 minuten nog niets horen, laten we het uw contactpersonen weten.' },
  en: { s: 'CareFlow: did you see this?', b: 'Dear NAAM,

We have not heard from you yet. Could you still complete the check-in?

Open CareFlow: ' + url + '

If we hear nothing in 30 minutes, we will let your contacts know.' },
  tr: { s: 'CareFlow: gordunuz mu?', b: 'Sayin NAAM,

Henuz sizden yanit almadik. Kontrolu tamamlar misiniz?

CareFlow: ' + url + '

30 dakika icinde yanit alamazsak kisilerinize haber verecegiz.' },
  ar: { s: 'CareFlow: هل رأيت هذا؟', b: 'عزيزي NAAM،

لم نتلق ردا منك بعد. هل يمكنك إكمال الفحص؟

افتح CareFlow: ' + url + '

إذا لم نسمع منك خلال 30 دقيقة فسنخبر جهات اتصالك.' }
};
const ESC = {
  nl: { s: 'CareFlow: geen reactie van NAAM', b: 'Beste,

NAAM heeft vandaag niet gereageerd op twee CareFlow-herinneringen (CHECK).

Adres: ADRES

Wilt u even contact opnemen of langsgaan?

Dit is een automatisch bericht van CareFlow, een studentenproject. CareFlow belt zelf geen 112, politie of huisarts. Is er direct gevaar? Bel zelf 112.' },
  en: { s: 'CareFlow: no response from NAAM', b: 'Hello,

NAAM has not responded to two CareFlow reminders today (CHECK).

Address: ADRES

Could you get in touch or drop by?

This is an automated message from CareFlow, a student project. CareFlow does not call 112, the police or a doctor itself. Immediate danger? Call 112 yourself.' },
  tr: { s: 'CareFlow: NAAM yanit vermedi', b: 'Merhaba,

NAAM bugun iki CareFlow hatirlatmasina yanit vermedi (CHECK).

Adres: ADRES

Iletisime gecer veya ugrar misiniz?

Bu, bir ogrenci projesi olan CareFlow tarafindan gonderilen otomatik bir mesajdir. CareFlow kendisi 112, polis veya doktor aramaz. Acil tehlike mi var? 112 yi kendiniz arayin.' },
  ar: { s: 'CareFlow: لا يوجد رد من NAAM', b: 'مرحبا،

لم يرد NAAM اليوم على تذكيرين من CareFlow (CHECK).

العنوان: ADRES

هل يمكنك التواصل أو المرور؟

هذه رسالة تلقائية من CareFlow، وهو مشروع طلابي. لا يتصل CareFlow بالرقم 112 أو الشرطة أو الطبيب. هل هناك خطر فوري؟ اتصل بالرقم 112 بنفسك.' }
};
const out = [];
for (const r of rows) {
  if (r.status !== 'open' && r.status !== 'herinnerd') { continue; }
  const created = new Date(r.created_at).getTime();
  if (isNaN(created)) { continue; }
  const age = (nowMs - created) / 60000;
  const u = users.find(x => x.session_id === r.session_id);
  if (!u) { continue; }
  const lang = R2[u.language] ? u.language : 'nl';
  const naam = u.name || 'CareFlow';
  if (r.status === 'open' && age >= 45) {
    out.push({ json: {
      action: 'herinnering2',
      check_id: r.check_id,
      session_id: r.session_id,
      to_list: u.email || '',
      subject: R2[lang].s,
      body: R2[lang].b.split('NAAM').join(naam)
    } });
  } else if (r.status === 'herinnerd' && age >= 75 && r.emergency_notified !== true) {
    const to = [];
    if (u.contact1_contact) { to.push(String(u.contact1_contact).trim()); }
    if (u.contact2_contact) { to.push(String(u.contact2_contact).trim()); }
    const gpOk = (u.consent_gp === true || u.consent_gp === 'true');
    if (gpOk && u.gp_contact && String(u.gp_contact).indexOf('@') > -1) { to.push(String(u.gp_contact).trim()); }
    if (to.length === 0) { continue; }
    const body = ESC[lang].b.split('NAAM').join(naam).split('CHECK').join(r.check_type).split('ADRES').join(u.address || '-');
    out.push({ json: {
      action: 'escalatie',
      check_id: r.check_id,
      session_id: r.session_id,
      to_list: to.join(','),
      subject: ESC[lang].s.split('NAAM').join(naam),
      body: body
    } });
  }
}
return out;
